<script>
const STORAGE_KEY = 'dockview-layout'
const AUTO_SAVE_DELAY = 1000 // 1 second debounce

export default {
  name: 'Desktop',
  components: {
    'dockview-vue': DockviewVue,
    'window': Window,
    'app-window': AppWindow,
    'log-viewer': LogViewer,
    'knowledge': KnowledgeViewVue,
    'knowledge_settings': KnowledgeSettingsVue,
    'profiles': ProfileViewVue,
    'home': CodxWelcomeView,
    'settings': ProjectSettingsVue,
    'wiki': WikiViewVue,
    'docs': DocsViewVue,
    'global-settings': GlobalSettingsVue,
    'tasks': KanbanContainerVue,
    'files': Files,
    'metrics': MetricsViewer,
    'account': AccountSettings,
    'file-explorer': FileExplorerVue,
    'projects': ProjectOverview,
    'activity': Wall,
    'chat': ChatView,
    'analytics': AnalyticsDashboard,
    'chat-logs': LogsAnalyzerDashboard,
    'team-channel': TeamChannel,
    'team-dm': TeamDM,
    'team-media-library': TeamMediaLibrary,
    'vibe-coding': VibeCodingView,
    'workspaces': WorkspacesList,
    tabComponent: Tab,
    ViewProperties
  },
  props: {
    storageKey: {
      type: String,
      default: STORAGE_KEY
    }
  },
  data() {
    return {
      dockviewApi: null,
      registeredComponents: {
        'window': Window,
        'app-window': AppWindow,
      },
      layoutRestored: false,
      autoSaveTimeout: null,
      currentViewName: null
    }
  },
  computed: {
    apps() {
      const { openApps } = this.$ui
      return Object.values(openApps)
    },
    panelTabIds() {
      return this.dockviewApi?.panels.map(p => p.id)
    },
    uiReady() {
      return this.$ui.uiReady
    },
    viewEditor() {
      return this.$storex.ui.viewEditor
    },
    activeProject() {
      return this.$storex.projects.activeProject
    }
  },
  watch: {
    apps(newVal) {
      const { panelTabIds } = this
      newVal
        .filter(({ tabId }) => !panelTabIds.includes(tabId))
        .forEach(app => this.addAppPanel(app))
      if (!newVal.length) {
        this.init()
      }
    },
    uiReady() {
      this.restoreLayout()
    },
    activeProject() {
      this.onActiveProjectChange()
    }
  },
  methods: {
    closeViewEditor() {
      this.$storex.ui.closeViewEditor()
    },
    init() {
      if (!this.panelTabIds.length) {
        this.$ui.showTab('home')
      }
    },
    addAppPanel(app) {
      if (!app?.tabId) return
      const component = app.component || 'app-window'
      const renderer = 'always'
      this.addPanel({
        id: app.tabId,
        title: app.name,
        component,
        renderer,
        params: {
          ...app.params || {},
          app
        }
      })
    },
    onReady(event) {
      this.dockviewApi = event.api
      this.$ui.setDesktopApi(this.dockviewApi)
      this.restoreLayout()
      this.dockviewApi.onDidAddPanel(this.onAddPanel.bind(this))
      this.dockviewApi.onDidRemovePanel(this.onRemovePanel.bind(this))
      this.dockviewApi.onDidLayoutChange(this.onLayoutChange.bind(this))
    },
    onAddPanel() {
      this.debouncedAutoSave()
    },
    onRemovePanel(panel) {
      this.$ui.closeApp(panel.params.app)
      this.debouncedAutoSave()
    },
    onLayoutChange() {
      this.debouncedAutoSave()
    },
    debouncedAutoSave() {
      if (this.autoSaveTimeout) {
        clearTimeout(this.autoSaveTimeout)
      }
      this.autoSaveTimeout = setTimeout(() => {
        this.autoSaveCurrentView()
      }, AUTO_SAVE_DELAY)
    },
    async autoSaveCurrentView() {
      const project = this.$storex.projects.activeProject
      if (!project || !this.currentViewName) return

      try {
        const layout = this.getLayout()
        const projectApi = project.$api
        if (!projectApi) return

        const view = {
          name: this.currentViewName,
          project_id: project.project_id,
          desktop: layout
        }

        await projectApi.views.save(view)
        this.$storex.ui.persistLastView({ 
          project_id: project.project_id, 
          view 
        })
      } catch (ex) {
        console.warn('Failed to auto-save view:', ex)
      }
    },
    async onActiveProjectChange() {
      if (!this.activeProject || !this.dockviewApi) return

      try {
        await this.$storex.ui.loadViews()
        await this.$storex.ui.restoreLastView()

        if (!this.$storex.ui.lastView) {
          this.init()
        }
      } catch (ex) {
        console.warn('Failed to switch project view:', ex)
        this.init()
      }
    },
    addPanel({ id, title, component = 'window', position, params, renderer }) {
      if (!this.dockviewApi) return
      if (!this.dockviewApi.panels.find(p => p.id === id)) {
        this.dockviewApi.addPanel({
          id,
          title,
          component,
          position,
          renderer,
          params: {
            ...params,
            tabName: title,
          },
          tabComponent: 'tabComponent'
        })
      }
    },
    removePanel(id) {
      if (!this.dockviewApi) return
      const panel = this.dockviewApi.getPanel(id)
      panel && this.dockviewApi.removePanel(panel)
    },
    registerComponent(name, component) {
      this.registeredComponents = {
        ...this.registeredComponents,
        [name]: component
      }
    },
    saveLayout() {
      if (!this.dockviewApi) return null
      const layout = this.dockviewApi.toJSON()
      localStorage.setItem(this.storageKey, JSON.stringify(layout))
      return layout
    },
    restoreLayout(layout = null) {
      if (this.layoutRestored) return true
      if (!this.dockviewApi || !this.uiReady) return false
      try {
        const data = layout || JSON.parse(localStorage.getItem(this.storageKey))
        if (!data) return false
        this.dockviewApi.fromJSON(data)
        this.dockviewApi.panels.forEach(panel => {
          if (panel.params.chat) {
            this.$chats.reloadChat(panel.params.chat)
          }
          this.$ui.showApp(panel.params.app)
        })
        this.init()
        this.layoutRestored = true
      } catch (e) {
        console.warn('Failed to restore dockview layout:', e)
        return false
      }
    },
    clearSavedLayout() {
      localStorage.removeItem(this.storageKey)
      this.$emit('layout-cleared')
    },
    getLayout() {
      return this.dockviewApi ? this.dockviewApi.toJSON() : null
    },
    setCurrentViewName(viewName) {
      this.currentViewName = viewName
    }
  },
  expose: [
    "addPanel",
    "removePanel",
    "registerComponent",
    "saveLayout",
    "restoreLayout",
    "clearSavedLayout",
    "getLayout",
    "setCurrentViewName"
  ]
}
</script>

